@Service
public class PedidoService {
    private final Counter pedidosCriados;
    private final Timer tempoCheckout;

    public PedidoService(MeterRegistry registry) {
        this.pedidosCriados = Counter.builder("pedidos.criados")
            .tag("canal", "web").register(registry);
        this.tempoCheckout = Timer.builder("checkout.duracao")
            .publishPercentiles(0.95, 0.99).register(registry);
    }

    public void finalizar(Pedido p) {
        tempoCheckout.record(() -> processar(p));
        pedidosCriados.increment();
    }
}
